-- PRWS-28: short chats between two collected heroes, written ahead of time and shown as speech bubbles in the city banner.
create table if not exists public.os_banter (
  id bigserial primary key,
  a text not null,
  b text not null,
  lines jsonb not null,
  source text not null default 'grok',
  created_at timestamptz not null default now(),
  constraint os_banter_pair check (a < b)
);
alter table public.os_banter enable row level security;
revoke all on public.os_banter from anon, authenticated;
create index if not exists os_banter_ab on public.os_banter (a, b);

-- Chats where both heroes are in the caller's collection. Owner-only heroes never appear here.
create or replace function public.os_banter()
returns jsonb
language plpgsql
security definer
set search_path to 'public'
as $function$
declare u uuid := auth.uid();
begin
  if u is null or not os_ok() then raise exception 'not allowed'; end if;
  return coalesce((
    select jsonb_agg(jsonb_build_object('a', x.a, 'b', x.b, 'lines', x.lines))
    from (
      select bt.a, bt.b, bt.lines from os_banter bt
      where exists (select 1 from os_hero h where h.uid = u and h.hero_id = bt.a)
        and exists (select 1 from os_hero h where h.uid = u and h.hero_id = bt.b)
        and exists (select 1 from os_hero_def d where d.id = bt.a)
        and exists (select 1 from os_hero_def d where d.id = bt.b)
      order by random() limit 60
    ) x), '[]'::jsonb);
end $function$;
revoke all on function public.os_banter() from public, anon;
grant execute on function public.os_banter() to authenticated;

insert into public.os_banter (a, b, lines)
select v.a, v.b, v.lines from (values
('delivery_rider','engineer','[{"who": "delivery_rider", "text": "Edith, your steam-powered cart is a game changer!"}, {"who": "engineer", "text": "Marco, it runs on enchanted coal I found in the mines!"}, {"who": "delivery_rider", "text": "Next delivery, we''ll race through every shortcut together!"}]'::jsonb),
