('delivery_rider','legionary','[{"who": "delivery_rider", "text": "Gaius my friend these shortcuts beat marching any day!"}, {"who": "legionary", "text": "Shortcuts lack the discipline of a proper Roman road Marco."}, {"who": "delivery_rider", "text": "But they get the hot stew here faster for us both!"}, {"who": "legionary", "text": "Very well let us advance with haste then."}]'::jsonb),
('delivery_rider','legionary','[{"who": "delivery_rider", "text": "Nothing like mining after a full day of deliveries!"}, {"who": "legionary", "text": "Mining is fine work but nothing beats a legion formation."}, {"who": "delivery_rider", "text": "We could race to the deepest ore who gets there first?"}, {"who": "legionary", "text": "Challenge accepted young courier prepare to lose."}]'::jsonb),
