('delivery_rider','legionary','[{"who": "delivery_rider", "text": "Fishing is relaxing after rushing meals all over town."}, {"who": "legionary", "text": "Patience in fishing mirrors the wait before a great battle."}, {"who": "delivery_rider", "text": "Exactly and the fish tastes amazing cooked fresh!"}, {"who": "legionary", "text": "Then let us catch enough for a feast worthy of Rome."}]'::jsonb),
