('delivery_rider','plague_doctor','[{"who": "delivery_rider", "text": "Doc, want to join my shortcut to the best fishing spot?"}, {"who": "plague_doctor", "text": "I prefer slow walks with my remedies in hand."}, {"who": "delivery_rider", "text": "Then we will stroll and swap stories from our worlds!"}, {"who": "plague_doctor", "text": "That gentle pace might be the perfect new cure."}]'::jsonb),
