('engineer','gangster','[{"who": "engineer", "text": "My steam-powered picker-upper could help us mine faster!"}, {"who": "gangster", "text": "Doll, in my day we''d call that a real swell invention."}, {"who": "engineer", "text": "Then let''s team up and dig up some treasures together."}, {"who": "gangster", "text": "You''ve got yourself a deal, partner."}]'::jsonb),
('engineer','hunter','[{"who": "engineer", "text": "Brokk, look at this spinning wheel I made from twigs!"}, {"who": "hunter", "text": "It turns so fast like magic wind."}, {"who": "engineer", "text": "We can use it to grind grain for fresh bread!"}, {"who": "hunter", "text": "Bread smells better than mammoth."}]'::jsonb),
('engineer','hunter','[{"who": "engineer", "text": "My new steam whistle will call everyone for dinner!"}, {"who": "hunter", "text": "Loud noise like thunder from your hands."}, {"who": "engineer", "text": "Exactly, now the whole town knows it''s stew time!"}, {"who": "hunter", "text": "Stew good, fire in pot amazing."}]'::jsonb),
('engineer','hunter','[{"who": "engineer", "text": "Brokk, help me test my ice-powered sled invention!"}, {"who": "hunter", "text": "Ice from my old home, now it moves us."}, {"who": "engineer", "text": "We will zoom down hills faster than any horse!"}, {"who": "hunter", "text": "Faster than running after big deer."}]'::jsonb),
('engineer','hunter','[{"who": "engineer", "text": "I built a lantern that lights up without fire, Brokk!"}, {"who": "hunter", "text": "Glow like stars but in your hands."}, {"who": "engineer", "text": "Perfect for exploring dark dungeons together!"}, {"who": "hunter", "text": "Hunt shadows with light magic."}]'::jsonb),
('engineer','paramedic','[{"who": "engineer", "text": "My new pulley system can hoist us right up that cliff!"}, {"who": "paramedic", "text": "Sounds fun Edith, but wear these helmets I reinforced."}, {"who": "engineer", "text": "With your clever padding it''ll be the safest flight ever!"}, {"who": "paramedic", "text": "That''s the spirit, now let''s check those ropes together."}]'::jsonb),
('gangster','paramedic','[{"who": "gangster", "text": "Maya, that glowing staff of yours sure beats a tommy gun."}, {"who": "paramedic", "text": "It''s all about helping our friends in the dungeon, Vincenzo."}, {"who": "gangster", "text": "Back in Chicago we''d call that real smooth magic."}, {"who": "paramedic", "text": "Just promise me you''ll dodge the next fireball better."}]'::jsonb),
('gangster','paramedic','[{"who": "gangster", "text": "You patch me up faster than any speakeasy medic, doll."}, {"who": "paramedic", "text": "It''s my job to keep heroes like you in one piece."}, {"who": "gangster", "text": "Reminds me of the time we outran trouble in the streets."}, {"who": "paramedic", "text": "Let''s focus on resting so you heal up properly now."}]'::jsonb),
('gangster','plague_doctor','[{"who": "gangster", "text": "Hey there, Doc, that beak mask of yours is quite the look!"}, {"who": "plague_doctor", "text": "It wards off the bad airs, my fedora friend."}, {"who": "gangster", "text": "In my line of work we call that style, not medicine!"}, {"who": "plague_doctor", "text": "Then perhaps my remedies could heal your shady deals."}]'::jsonb),
('gangster','plague_doctor','[{"who": "gangster", "text": "You look like you stepped out of a spooky storybook, pal."}, {"who": "plague_doctor", "text": "And you dress as if the jazz never stopped playing."}, {"who": "gangster", "text": "We could team up and run this town smoother than silk!"}, {"who": "plague_doctor", "text": "Only if your angles include herbal tonics for all."}]'::jsonb),
('gangster','plague_doctor','[{"who": "gangster", "text": "That mask hides a sweet heart, I can tell from here."}, {"who": "plague_doctor", "text": "Your smooth words might charm even the old plague."}, {"who": "gangster", "text": "Stick with me and we''ll turn frowns into big smiles!"}, {"who": "plague_doctor", "text": "Very well, but my potions stay part of the plan."}]'::jsonb),
('gangster','plague_doctor','[{"who": "gangster", "text": "Doc, your old remedies beat any tonic from my era."}, {"who": "plague_doctor", "text": "Your loyalty to friends inspires even a gloomy healer."}, {"who": "gangster", "text": "Together we make quite the unbeatable crew, huh?"}, {"who": "plague_doctor", "text": "Indeed, a gangster and a plague doctor, what a pair."}]'::jsonb),
('gangster','will_slapton','[{"who": "will_slapton", "text": "This dungeon crawl feels just like a blockbuster scene."}, {"who": "gangster", "text": "Stick with me, pal, and we''ll make it a sure thing."}, {"who": "will_slapton", "text": "Your charm could light up any dark cavern we face."}, {"who": "gangster", "text": "And your dramatic flair keeps the whole crew smiling."}]'::jsonb),
('hunter','legionary','[{"who": "hunter", "text": "Big walls everywhere! How you build so tall?"}, {"who": "legionary", "text": "With Roman engineering and legion discipline, my friend."}, {"who": "hunter", "text": "Fire in the square dances pretty like sky lights."}, {"who": "legionary", "text": "That is our eternal flame honoring the empire."}]'::jsonb),
('hunter','legionary','[{"who": "legionary", "text": "Form ranks, hunter! We shall march to the dungeon together."}, {"who": "hunter", "text": "March? I run with spear after big meat."}, {"who": "legionary", "text": "Order brings victory where chaos fails."}, {"who": "hunter", "text": "Your shiny helmet makes good fire mirror."}]'::jsonb),
('hunter','legionary','[{"who": "hunter", "text": "This fish tastes better cooked on hot rocks."}, {"who": "legionary", "text": "Nonsense, it requires proper Roman spices and grill."}, {"who": "hunter", "text": "Spices? Just fire and hungry belly."}, {"who": "legionary", "text": "Even the gods appreciate a well-ordered feast."}]'::jsonb),
('hunter','legionary','[{"who": "legionary", "text": "My shield and your spear shall conquer any beast."}, {"who": "hunter", "text": "Beast runs from big fire I make."}, {"who": "legionary", "text": "Then we combine tactics and flame for glory."}, {"who": "hunter", "text": "Your metal clothes funny but strong like mammoth."}]'::jsonb),
('hunter','office_worker','[{"who": "hunter", "text": "Big glowing rock make fire without wood! Magic!"}, {"who": "office_worker", "text": "That is the enchanted lantern Brokk I miss my old desk lamp."}, {"who": "hunter", "text": "We hunt mammoth with this bright stick!"}, {"who": "office_worker", "text": "Or we could organize the mining tools by size instead."}]'::jsonb),
('hunter','office_worker','[{"who": "hunter", "text": "Your talking box shows many tiny marks what is it?"}, {"who": "office_worker", "text": "My old spreadsheet Brokk it kept my whole life in order."}, {"who": "hunter", "text": "Marks on hide better for tracking big beasts!"}, {"who": "office_worker", "text": "True but I still miss sorting rows by favorite color."}]'::jsonb),
('hunter','office_worker','[{"who": "hunter", "text": "We chase shiny fish in river then roast them!"}, {"who": "office_worker", "text": "That sounds fun I used to file reports after lunch."}, {"who": "hunter", "text": "No reports only fire and full belly today!"}, {"who": "office_worker", "text": "Alright you win lets make the biggest fish feast ever."}]'::jsonb),
('hunter','paramedic','[{"who": "hunter", "text": "I caught huge fish. We roast it over big flames now?"}, {"who": "paramedic", "text": "Brokk, let me clean and cook it safely so no one gets sick."}, {"who": "hunter", "text": "Fire makes meat better. You will see."}, {"who": "paramedic", "text": "Safety first, then we enjoy the feast together."}]'::jsonb),
('hunter','will_slapton','[{"who": "hunter", "text": "Fire so bright in your metal box. Like magic sun."}, {"who": "will_slapton", "text": "That''s my portable grill, Brokk. Lights up for epic feasts!"}, {"who": "hunter", "text": "We roast big meat now? My spear ready for hunt."}, {"who": "will_slapton", "text": "Absolutely, my friend. Let''s make a feast worthy of legends!"}]'::jsonb),
('hunter','will_slapton','[{"who": "will_slapton", "text": "Brokk, this dungeon glows like a movie set. Action!"}, {"who": "hunter", "text": "Strange glowing rocks. They warm like good fire pit."}, {"who": "will_slapton", "text": "We''ll battle beasts and emerge as triumphant heroes!"}, {"who": "hunter", "text": "Yes. I like big fight and bigger victory meat after."}]'::jsonb),
('hunter','will_slapton','[{"who": "hunter", "text": "Your clothes shine like fresh ice. How you hunt in that?"}, {"who": "will_slapton", "text": "It''s my signature look, Brokk. Cameras loved it back home."}, {"who": "hunter", "text": "No cameras here. Only friends and good fishing spots."}, {"who": "will_slapton", "text": "Then let''s fish together and create our own grand story!"}]'::jsonb),
('hunter','will_slapton','[{"who": "will_slapton", "text": "The way you track game is pure cinema, Brokk. Brilliant!"}, {"who": "hunter", "text": "Tracks easy when snow fresh. You move loud like thunder."}, {"who": "will_slapton", "text": "Guilty as charged. But your skills steal every scene!"}, {"who": "hunter", "text": "We hunt as pair. You yell, I strike. Big meat for all."}]'::jsonb),
('legionary','plague_doctor','[{"who": "legionary", "text": "Your cloak billows like a standard in the wind, friend."}, {"who": "plague_doctor", "text": "And your sandals carry the dust of forgotten empires."}, {"who": "legionary", "text": "Together we could conquer any ailment or foe!"}, {"who": "plague_doctor", "text": "With order and kindness, the realm stays bright."}]'::jsonb),
('legionary','plague_doctor','[{"who": "legionary", "text": "I miss the baths of Rome on these chilly mining days."}, {"who": "plague_doctor", "text": "My remedies can ease those aches, brave soldier."}, {"who": "legionary", "text": "Your heart beneath the mask is warmer than any forum."}, {"who": "plague_doctor", "text": "And your discipline inspires even this gloomy beak."}]'::jsonb),
('office_worker','plague_doctor','[{"who": "office_worker", "text": "Doctor Albrecht, your mask looks so mysterious!"}, {"who": "plague_doctor", "text": "It wards off bad airs, my anxious friend."}, {"who": "office_worker", "text": "I miss my desk and coffee, but this adventure is nice."}, {"who": "plague_doctor", "text": "Then let us brew a cheerful herbal tonic together!"}]'::jsonb),
('office_worker','plague_doctor','[{"who": "office_worker", "text": "Your remedies seem so old yet kind of magical."}, {"who": "plague_doctor", "text": "They have healed many through the centuries, Kevin."}, {"who": "office_worker", "text": "I wish I had my spreadsheets to organize them."}, {"who": "plague_doctor", "text": "We can sort herbs by color in the meadow instead!"}]'::jsonb),
('office_worker','plague_doctor','[{"who": "plague_doctor", "text": "Your talk of desks and staples puzzles me, friend."}, {"who": "office_worker", "text": "They helped me organize my whole busy world."}, {"who": "plague_doctor", "text": "Here we organize by laughter and shared quests."}, {"who": "office_worker", "text": "That sounds way better than my old routines!"}]'::jsonb),
('office_worker','plague_doctor','[{"who": "office_worker", "text": "Albrecht, your beak mask makes me smile every time."}, {"who": "plague_doctor", "text": "It hides a sweet heart beneath the gloom."}, {"who": "office_worker", "text": "I could use a sweet remedy for my worries today."}, {"who": "plague_doctor", "text": "Then join me for a sunny walk through the flowers!"}]'::jsonb),
('paramedic','plague_doctor','[{"who": "paramedic", "text": "Doctor Albrecht your mask looks so mysterious!"}, {"who": "plague_doctor", "text": "It keeps the bad airs away dear Maya."}, {"who": "paramedic", "text": "Let me check that cut on your wing it needs a clean bandage."}, {"who": "plague_doctor", "text": "Your gentle hands remind me why I became a healer."}]'::jsonb),
('paramedic','plague_doctor','[{"who": "plague_doctor", "text": "This dungeon air is thick with ill humors Maya."}, {"who": "paramedic", "text": "Stay close and I will watch your breathing carefully."}, {"who": "plague_doctor", "text": "Your modern worry is strangely comforting."}, {"who": "paramedic", "text": "We make a great team even across centuries."}]'::jsonb),
('paramedic','plague_doctor','[{"who": "paramedic", "text": "Albrecht you cannot use leeches on that poor knight!"}, {"who": "plague_doctor", "text": "But my remedies have served for ages my friend."}, {"who": "paramedic", "text": "Try my clean wraps and herbs instead they work faster."}, {"who": "plague_doctor", "text": "Your bossy kindness feels like a warm spring breeze."}]'::jsonb),
('paramedic','plague_doctor','[{"who": "plague_doctor", "text": "Maya your bright clothes cheer even the gloomiest day."}, {"who": "paramedic", "text": "Thank you now let me fix that mask strap it is loose."}, {"who": "plague_doctor", "text": "You fuss over me like a mother hen from the future."}, {"who": "paramedic", "text": "Someone has to keep my favorite plague doctor safe!"}]'::jsonb),
('paramedic','will_slapton','[{"who": "paramedic", "text": "Will, that dramatic leap into the dungeon was risky!"}, {"who": "will_slapton", "text": "But my fans expect a heroic entrance every time!"}, {"who": "paramedic", "text": "Next time, let''s both wear helmets for safety."}, {"who": "will_slapton", "text": "Only if it comes with a glamorous movie montage!"}]'::jsonb),
('paramedic','will_slapton','[{"who": "paramedic", "text": "Your movie-star flair lights up these cobblestone streets."}, {"who": "will_slapton", "text": "Aldermere needs a leading man like me to shine bright!"}, {"who": "paramedic", "text": "Just promise no wild stunts without my first aid kit."}, {"who": "will_slapton", "text": "Deal, as long as you join my next epic quest scene!"}]'::jsonb),
('paramedic','will_slapton','[{"who": "paramedic", "text": "That cheeky goblin''s joke was rude, but no slapping!"}, {"who": "will_slapton", "text": "My famous slap keeps the set polite and fun!"}, {"who": "paramedic", "text": "Let''s use words and bandages to handle trouble instead."}, {"who": "will_slapton", "text": "Fine, but my dramatic flair still saves the day!"}]'::jsonb),
('paramedic','will_slapton','[{"who": "paramedic", "text": "Fishing by the river is peaceful after a busy rescue."}, {"who": "will_slapton", "text": "I shall catch the biggest fish for our victory feast!"}, {"who": "paramedic", "text": "Great, but reel it in slowly to avoid any injuries."}, {"who": "will_slapton", "text": "With you watching, it''s the perfect blockbuster moment!"}]'::jsonb),
('plague_doctor','will_slapton','[{"who": "will_slapton", "text": "Action hero meets the mysterious plague doctor!"}, {"who": "plague_doctor", "text": "Your flair reminds me of festivals in my old village."}, {"who": "will_slapton", "text": "Let us team up and save the day with style!"}, {"who": "plague_doctor", "text": "Together we shall bring hope and cheer to all."}]'::jsonb),
('plague_doctor','will_slapton','[{"who": "plague_doctor", "text": "These herbs from my era could help with any ailment."}, {"who": "will_slapton", "text": "Your wisdom is more dramatic than my best scenes!"}, {"who": "plague_doctor", "text": "And your energy lights up even the darkest dungeon."}, {"who": "will_slapton", "text": "We are unstoppable friends in this fantasy world!"}]'::jsonb),
('plague_doctor','will_slapton','[{"who": "will_slapton", "text": "Your beak mask would steal every scene back home!"}, {"who": "plague_doctor", "text": "Your bold spirit would rally my whole town."}, {"who": "will_slapton", "text": "Let us fish together and swap the tallest tales!"}, {"who": "plague_doctor", "text": "What a delightful way to blend our two eras."}]'::jsonb),
('delivery_rider','gangster','[{"who": "delivery_rider", "text": "Hey Vincenzo, wanna race me to the old oak tree?"}, {"who": "gangster", "text": "Only if we make it a friendly wager, pal."}, {"who": "delivery_rider", "text": "Loser buys the winner a big slice of pie!"}, {"who": "gangster", "text": "You''re on, kid. This suit don''t slow me down."}]'::jsonb),
('delivery_rider','gangster','[{"who": "delivery_rider", "text": "Vincenzo, these dungeon critters are faster than traffic!"}, {"who": "gangster", "text": "Stick with me, Marco. I got a few tricks from the old days."}, {"who": "delivery_rider", "text": "Your smooth moves mixed with my shortcuts? Unbeatable!"}, {"who": "gangster", "text": "That''s the spirit. Let''s grab some treasure together."}]'::jsonb),
('delivery_rider','gangster','[{"who": "delivery_rider", "text": "Man, fishing here beats dodging city bikes any day!"}, {"who": "gangster", "text": "Back in my time we called it relaxing with a rod, see?"}, {"who": "delivery_rider", "text": "Haha, your fancy hat makes the fish jump right in!"}, {"who": "gangster", "text": "And your speedy feet keep us ahead of the big ones."}]'::jsonb),
('delivery_rider','gangster','[{"who": "delivery_rider", "text": "Vincenzo, your suit is perfect for fancy feasts in town!"}, {"who": "gangster", "text": "And your quick legs get the fresh ingredients fast."}, {"who": "delivery_rider", "text": "Teamwork makes the best meals in any era!"}, {"who": "gangster", "text": "You said it, kid. Here''s to our crew."}]'::jsonb),
('engineer','office_worker','[{"who": "engineer", "text": "I have engineered a steam-powered fishing rod Kevin!"}, {"who": "office_worker", "text": "Wow Edith, does it also brew a perfect cup of coffee?"}, {"who": "engineer", "text": "Not yet, but it reels in trout while whistling jolly tunes!"}, {"who": "office_worker", "text": "Then I shall join you, my tired feet need this adventure."}]'::jsonb),
('engineer','office_worker','[{"who": "engineer", "text": "Behold my pulley system for lifting heavy treasure chests!"}, {"who": "office_worker", "text": "Impressive Edith, it reminds me of stacking files neatly."}, {"who": "engineer", "text": "We shall haul riches while humming Victorian marching songs!"}, {"who": "office_worker", "text": "Count me in, as long as there is a warm meal waiting after."}]'::jsonb),
('engineer','will_slapton','[{"who": "engineer", "text": "Will, my new steam-powered boots are a marvel!"}, {"who": "will_slapton", "text": "Edith, they look ready for a blockbuster chase scene!"}, {"who": "engineer", "text": "Just wait until we dash through the dungeon together!"}]'::jsonb),
('engineer','will_slapton','[{"who": "will_slapton", "text": "Edith, this glowing sword feels like pure movie magic!"}, {"who": "engineer", "text": "I added a few gears to make it hum with power!"}, {"who": "will_slapton", "text": "You''re the brilliant inventor every hero needs!"}, {"who": "engineer", "text": "And you''re the dramatic flair that lights up Aldermere!"}]'::jsonb),
('engineer','will_slapton','[{"who": "engineer", "text": "My latest gadget turns river water into fizzy lemonade!"}, {"who": "will_slapton", "text": "Edith, that calls for a victory picnic under the stars!"}, {"who": "engineer", "text": "We can sip it after fishing up some shiny treasures!"}]'::jsonb),
('engineer','will_slapton','[{"who": "will_slapton", "text": "Edith, your clockwork bird just sang a perfect tune!"}, {"who": "engineer", "text": "It even helps me spot the best mining spots from above!"}, {"who": "will_slapton", "text": "With your inventions, every adventure feels epic!"}, {"who": "engineer", "text": "And your spirit makes it all wonderfully fun!"}]'::jsonb),
('gangster','legionary','[{"who": "gangster", "text": "Gaius you march like you own the whole street."}, {"who": "legionary", "text": "A Roman legionary brings the glory of Rome everywhere."}, {"who": "gangster", "text": "In Chicago we stroll with a little more swagger."}, {"who": "legionary", "text": "Swagger is no match for the discipline of the legions."}]'::jsonb),
('delivery_rider','office_worker','[{"who": "delivery_rider", "text": "Hey Kevin, I just zoomed through the forest on my bike!"}, {"who": "office_worker", "text": "Whoa Marco, I miss my quiet desk already."}, {"who": "delivery_rider", "text": "Race you to the dungeon, buddy!"}, {"who": "office_worker", "text": "Only if we stop for a nice cup of coffee first."}]'::jsonb),
('delivery_rider','office_worker','[{"who": "delivery_rider", "text": "Kevin, these magical roads have the best shortcuts ever!"}, {"who": "office_worker", "text": "I wish my spreadsheets could sort out these monsters."}, {"who": "delivery_rider", "text": "Forget papers, let''s go fishing together!"}, {"who": "office_worker", "text": "Sounds relaxing, as long as I get a break from the hurry."}]'::jsonb),
('delivery_rider','office_worker','[{"who": "delivery_rider", "text": "I''m always hungry after delivering through the hills!"}, {"who": "office_worker", "text": "I could really use my stapler for these adventure maps."}, {"who": "delivery_rider", "text": "Let''s cook up something yummy in the city square!"}, {"who": "office_worker", "text": "That beats my old lunch at the office any day."}]'::jsonb),
('delivery_rider','office_worker','[{"who": "delivery_rider", "text": "Kevin, the magic circle sure picked a fun pair like us!"}, {"who": "office_worker", "text": "True, but I still dream of my cozy desk chair."}, {"who": "delivery_rider", "text": "Come on, mining gems will cheer you right up!"}, {"who": "office_worker", "text": "Okay, let''s make it an adventure to remember."}]'::jsonb),
('engineer','legionary','[{"who": "legionary", "text": "Edith, your metal birds soar like eagles over the Forum."}, {"who": "engineer", "text": "Thank you, Gaius! I used cogs from a broken pocket watch."}, {"who": "legionary", "text": "In my time we sent messages by swift riders and ships."}, {"who": "engineer", "text": "Now imagine them flying on my little wings instead!"}]'::jsonb),
('engineer','plague_doctor','[{"who": "engineer", "text": "Doctor, your mask is so mysterious and grand!"}, {"who": "plague_doctor", "text": "It wards off the bad airs of the plague, dear Edith."}, {"who": "engineer", "text": "I could build a steam powered version with gears!"}, {"who": "plague_doctor", "text": "Your inventions always bring a smile beneath my beak."}]'::jsonb),
('engineer','plague_doctor','[{"who": "engineer", "text": "Mixing herbs is like crafting a clever machine!"}, {"who": "plague_doctor", "text": "These remedies have healed souls for centuries, my friend."}, {"who": "engineer", "text": "Let me add a little spring to make it sprinkle evenly!"}, {"who": "plague_doctor", "text": "Your bright spirit turns my gloomy days quite sunny."}]'::jsonb),
('engineer','plague_doctor','[{"who": "engineer", "text": "The dungeon lanterns could use some clockwork upgrades!"}, {"who": "plague_doctor", "text": "In my time we carried simple torches through the dark."}, {"who": "engineer", "text": "Watch this contraption spin and glow like magic!"}, {"who": "plague_doctor", "text": "Even an old plague doctor finds wonder in your work."}]'::jsonb),
('engineer','plague_doctor','[{"who": "engineer", "text": "Your poultices smell like a proper London garden!"}, {"who": "plague_doctor", "text": "They soothe the body as your gadgets soothe the mind."}, {"who": "engineer", "text": "Together we could invent the ultimate healing device!"}, {"who": "plague_doctor", "text": "With your cheer, even my remedies feel twice as sweet."}]'::jsonb),
('legionary','will_slapton','[{"who": "legionary", "text": "Will, your dramatic speeches echo like Senate orations."}, {"who": "will_slapton", "text": "Thanks Gaius! I once won an award for my epic monologues."}, {"who": "legionary", "text": "In Rome we award laurel wreaths for such bold words."}, {"who": "will_slapton", "text": "A leafy crown sounds way more stylish than shiny metal."}]'::jsonb),
('legionary','will_slapton','[{"who": "will_slapton", "text": "Gaius, teach me your famous Roman marching chant!"}, {"who": "legionary", "text": "Very well! Left foot first, keep the formation tight."}, {"who": "will_slapton", "text": "This is gonna look amazing in my next action movie."}, {"who": "legionary", "text": "Just remember, no slapping during the solemn march."}]'::jsonb),
('office_worker','paramedic','[{"who": "office_worker", "text": "Fishing here beats staring at spreadsheets all day."}, {"who": "paramedic", "text": "Kevin, keep your hands away from those sharp hooks please."}, {"who": "office_worker", "text": "This era has way more adventure than my office life."}, {"who": "paramedic", "text": "True, but safety first so we both make it home smiling."}]'::jsonb),
