('office_worker','paramedic','[{"who": "office_worker", "text": "Maya, these fantasy herbs remind me of organizing files."}, {"who": "paramedic", "text": "Focus on sorting them safely so no one gets a rash."}, {"who": "office_worker", "text": "My old stapler never helped me brew potions like this."}, {"who": "paramedic", "text": "And my ambulance never flew on dragon wings either."}]'::jsonb),
('engineer','legionary','[{"who": "engineer", "text": "My steam powered cart could carry your entire shield wall!"}, {"who": "legionary", "text": "A fine idea, though my men prefer marching in perfect step."}, {"who": "engineer", "text": "Imagine them parading through Aldermere on my invention!"}, {"who": "legionary", "text": "They would look splendid upholding Roman discipline."}]'::jsonb),
('engineer','legionary','[{"who": "engineer", "text": "Gaius, your helmet gave me the best idea for a new drill!"}, {"who": "legionary", "text": "Use it wisely, for Roman gear serves the empire''s glory."}, {"who": "engineer", "text": "This contraption will dig tunnels faster than any shovel!"}, {"who": "legionary", "text": "Then we shall march through them in orderly fashion."}]'::jsonb),
('engineer','legionary','[{"who": "engineer", "text": "I combined your sandal straps with my gears for boots!"}, {"who": "legionary", "text": "They look sturdy enough for a long march to battle."}, {"who": "engineer", "text": "Now you can charge ahead without tripping on roots!"}, {"who": "legionary", "text": "Excellent, let us test them on the path to honor."}]'::jsonb)
